      if (env.BUILDER_GITHUB_STATS_SNAPSHOT)  configOverrides.githubStatsSnapshot  = env.BUILDER_GITHUB_STATS_SNAPSHOT;
      if (env.BUILDER_YOUTUBE_STATS_MODE)     configOverrides.youtubeStatsMode     = env.BUILDER_YOUTUBE_STATS_MODE;
      if (env.BUILDER_GITHUB_STATS_MODE)      configOverrides.githubStatsMode      = env.BUILDER_GITHUB_STATS_MODE;
      return new Response(JSON.stringify(configOverrides), {
        status: 200,
        headers: {
          'content-type': 'application/json',
          'access-control-allow-origin': '*'
        }
      });
